    "sbom.title": "This is a {fmt} document",
    "sbom.what.CycloneDX": "CycloneDX is an OWASP / ECMA-424 standard for a machine-readable bill of materials. Every release of {name} ships one JSON file per platform listing each component, its version, licence and package URL — the input for the CVE lookup and every number on this site.",
    "sbom.what.SPDX": "SPDX is a Linux Foundation / ISO/IEC 5962 standard for software bills of materials. This product's JSON file lists its packages, versions, licences and relationships — the input for every number on this site.",
    "sbom.format": "Format", "sbom.docver": "Document version", "sbom.generated": "Generated", "sbom.serial": "serial {s}…", "sbom.describes": "Describes",
