    "sbom.structure": "Document structure", "sbom.types": "Component types", "sbom.missing": "Not in the file", "sbom.missing_note": "— the dependency graph and VEX are listed under Actions. The CVEs shown on this site are added at build time from OSV.dev; they are never written into the SBOM file.",
    "sbom.props": "Custom properties / references", "sbom.props_note.CycloneDX": "Vendor-specific properties (e.g. where a component ships and runs) travel inside the file as name/value pairs.", "sbom.props_note.SPDX": "externalRefs carry purl, CPE and other identifiers.",
    "sbom.anatomy": "Anatomy of one component",
    "f.type": "What kind of thing it is: library, application, data (AI model), …", "f.bom-ref": "Unique id inside this document; other parts (dependencies, vulnerabilities) point to it.", "f.name": "Component name as published upstream.", "f.version": "Exact version that ships in this release.", "f.purl": "Package URL: ecosystem + name + version. The key for CVE lookups (OSV.dev).", "f.licenses": "SPDX licence id or expression, as declared upstream.", "f.externalReferences": "Where to find the source: website, VCS, source mirror.", "f.properties": "Vendor extensions as name/value pairs.",
    "f.SPDXID": "Unique id of the package inside this document.", "f.versionInfo": "Exact version that ships.", "f.externalRefs": "Identifiers: purl (for CVE lookup), CPE, security references.", "f.licenseConcluded": "Licence concluded by the SBOM author (SPDX expression).", "f.supplier": "Who supplies the package.", "f.checksums": "Hashes of the package file.", "f.primaryPackagePurpose": "LIBRARY, APPLICATION, FIRMWARE, OPERATING-SYSTEM, …",
    "about.title": "How it works", "about.lead": "Everything on this site is generated from the SBOM files published with each release. No agent runs in the product and nothing is uploaded.",
    "about.step": "Step {n}",
    "about.s1.t": "A release publishes an SBOM", "about.s1.d": "One CycloneDX or SPDX JSON file per platform per release, ideally with a checksum file.",
    "about.s2.t": "The build reads every release", "about.s2.d": "tools/build_site.py lists components, licences and ecosystems and diffs each release against the previous one.",
    "about.s3.t": "Enrich with public data", "about.s3.d": "Each package URL is looked up on OSV.dev for CVEs and fix versions; CISA KEV marks exploited ones; EPSS gives exploit probability.",
    "about.s4.t": "Score and publish", "about.s4.d": "Maturity, ranked actions and history become static JSON shown by this page. Rebuilt weekly and on every release.",
    "about.cve": "Reading a CVE row", "about.cve.1": "Severity — CVSS base score from the advisory (critical ≥ 9, high ≥ 7, medium ≥ 4).", "about.cve.2": "KEV — listed by CISA as exploited in the wild: fix first.", "about.cve.3": "EPSS — probability that a CVE is exploited in the next 30 days.", "about.cve.4": "Fix — lowest published version above the one shipped.", "about.cve.5": "Unknown — advisory without a CVSS score.", "about.cve.note": "A CVE in a library is not automatically exploitable in the product. Triage with a VEX statement.",
    "about.maturity": "Maturity score (0–100)", "about.maturity.note": "Weighted average of seven checks. Levels: {levels} (score thresholds {th}). A transparent heuristic for tracking progress, not a certification.",
    "about.glossary": "Glossary", "about.g.sbom": "SBOM — list of every component inside a product.", "about.g.cdx": "CycloneDX / SPDX — the two main SBOM standards (JSON).", "about.g.purl": "purl — package URL, e.g. pkg:cargo/rsa@0.9.10.", "about.g.ntia": "NTIA minimum elements — the 7 data fields a usable SBOM needs.", "about.g.vex": "VEX — statement saying whether a CVE really affects the product.", "about.g.cra": "CRA — EU Cyber Resilience Act: requires an SBOM and vulnerability handling.",
    "about.products": "Any kind of product", "about.products.d": "Desktop, mobile, web, embedded/firmware, server or library — anything that can produce a CycloneDX or SPDX JSON. Components with a package URL (Maven, npm, PyPI, Cargo, Go, NuGet, Pub, Swift …) get CVE checks; components without one are listed but flagged as a blind spot.",
    "about.add": "Add your product", "about.add.1": "python tools/import_sbom.py bom.json --product my-app --name \"My App\" --type mobile --version 2.4.0 --variant android", "about.add.2": "python tools/build_site.py", "about.add.3": "Open the site — your product is there, in both languages if you gave both taglines.", "about.add.docs": "Full guide: docs/ADDING-A-PRODUCT.md",
    "about.use": "Use it", "about.use.1": "Present: swipeable slides, arrow keys on desktop.", "about.use.2": "History: tap a release to see what changed.", "about.use.3": "Compare CVE: any two releases or platforms; shows new, fixed and open.", "about.use.4": "SBOM file tab: raw structure, one annotated component and downloads.", "about.use.5": "Every view has its own link — share the address.", "about.use.6": "Language switch PL / EN in the top bar; “Tour” replays the guided tour.",
    "present.sub": "Software Bill of Materials", "present.inside": "What is inside", "present.history": "History of changes", "present.latest": "Latest release: {v}", "present.posture": "Vulnerability posture", "present.maturity": "Maturity — Level {n}: {name}", "present.actions": "Recommended actions",
    "present.releases": "{n} releases archived, {a} → {b}.", "present.against": "Against {v}: +{a} added, −{r} removed, ~{c} upgraded.", "present.cve_line": "CVEs: {new} new · {fixed} fixed · {open} still open.", "present.no_fix": "no fix yet", "present.exit": "Exit", "present.fs": "Fullscreen", "present.eco": "Mostly {list}.",
    "tour.next": "Next", "tour.back": "Back", "tour.skip": "Skip", "tour.done": "Done", "tour.of": "{i} / {n}",
    "tour.home.1.t": "Welcome 👋", "tour.home.1.d": "This site shows the Software Bill of Materials (SBOM) of every product: what is inside, how it changed, which CVEs it carries and what to do next. A 30-second tour:",
    "tour.home.2.t": "Language", "tour.home.2.d": "Switch between Polish and English at any time. Your choice is remembered.",
    "tour.home.3.t": "Products", "tour.home.3.d": "One card per product (desktop, mobile, web, embedded …). Each row is a platform build — tap it to open the details.",
    "tour.home.4.t": "Present mode", "tour.home.4.d": "▶ Present turns the data into swipeable slides for a meeting. Works on phones too.",
    "tour.home.5.t": "How it works", "tour.home.5.d": "The pipeline, glossary, scoring rules and how to add your own product.",
    "tour.home.6.t": "Replay any time", "tour.home.6.d": "This button restarts the tour for the page you are on.",
    "tour.p.1.t": "Platforms", "tour.p.1.d": "A product can have several builds (Windows, Linux, Android, firmware …). Pick one.",
    "tour.p.2.t": "Key numbers", "tour.p.2.d": "Latest release, number of components, known CVEs and the maturity level at a glance.",
    "tour.p.3.t": "Tabs", "tour.p.3.d": "History = what changed per release · Compare CVE = any two releases side by side · Actions = what to fix first · Maturity = how complete and safe the SBOM is · Components = full list · SBOM file = the raw standard file.",
    "tour.p.4.t": "Present", "tour.p.4.d": "Opens this product as slides — swipe or use arrow keys.",
