    "ir.tier.likely": "Prawdopodobne (EPSS ≥ 10%)", "ir.tier.likely_d": "Nie znaleziono PoC, ale modele oceniają wykorzystanie jako prawdopodobne. Łataj wkrótce.",
    "ir.tier.routine": "Rutynowe", "ir.tier.routine_d": "Zwykłe zarządzanie podatnościami.",
    "ir.tier_col": "Poziom", "ir.f_all": "Wszystkie poziomy", "ir.kev_yes": "KEV", "ir.ransom": "ransomware",
    "ir.nopoc": "Dla tego produktu nie zebrano danych o PoC, więc poziom PoC jest pusty, a część CVE może być oceniona niżej, niż powinna. Zbuduj go ponownie przez scripts/cve-check.py.",
    "ir.poc_caveat": "PoC = publiczne repozytoria GitHub nazwane od CVE (nomi-sec/PoC-in-GitHub). To dopasowanie nazwy, nie dowód działającego exploita, a ? oznacza brak danych. Brak w KEV nie znaczy braku wykorzystania: KEV zawiera tylko to, co potwierdziła CISA.",
    "ir.triage_title": "Czy to incydent?", "ir.triage_lead": "Wybierz CVE i odpowiedz na trzy pytania o TWOJE środowisko. Sam poziom nigdy nie tworzy incydentu.",
